import os
os.chdir('/root/autodl-tmp/trace-verdict-study')

# Fix config.py
with open('config.py', 'r') as f:
    lines = f.readlines()

# Find and remove vLLM-related lines
skip_lines = set()
for i, line in enumerate(lines):
    if 'vLLM backend' in line and 'colocate mode' in line:
        skip_lines.add(i)
    if 'use_vllm' in line and 'field(' in line:
        skip_lines.add(i)
    if 'vllm_mode' in line and 'field(' in line:
        skip_lines.add(i)
    if 'vllm_gpu_memory_utilization' in line and ('field(' in line or 'default=' in line):
        skip_lines.add(i)
    if 'vllm_enable_sleep_mode' in line and ('field(' in line or 'default=' in line):
        skip_lines.add(i)
    # Also catch continuation lines for multi-line field defs
    if i > 0 and (i-1) in skip_lines and line.strip().startswith('default='):
        skip_lines.add(i)
    if i > 0 and (i-1) in skip_lines and line.strip() == ')':
        skip_lines.add(i)

# Re-scan for continuation lines (multi-line fields)
changed = True
while changed:
    changed = False
    for i, line in enumerate(lines):
        if i in skip_lines:
            continue
        if i > 0 and (i-1) in skip_lines:
            stripped = line.strip()
            if stripped.startswith('default=') or stripped == ')' or stripped.startswith('metadata='):
                skip_lines.add(i)
                changed = True

new_lines = [l for i, l in enumerate(lines) if i not in skip_lines]
with open('config.py', 'w') as f:
    f.writelines(new_lines)
print(f'config.py: removed {len(skip_lines)} lines')

# Fix train_grpo.py
with open('train_grpo.py', 'r') as f:
    lines = f.readlines()

skip_lines = set()
for i, line in enumerate(lines):
    if 'vLLM colocate' in line:
        skip_lines.add(i)
    if 'use_vllm=grpo_args.use_vllm' in line:
        skip_lines.add(i)
    if 'vllm_mode=grpo_args.vllm_mode' in line:
        skip_lines.add(i)
    if 'vllm_gpu_memory_utilization=grpo_args.vllm_gpu_memory_utilization' in line:
        skip_lines.add(i)
    if 'vllm_enable_sleep_mode=grpo_args.vllm_enable_sleep_mode' in line:
        skip_lines.add(i)

new_lines = [l for i, l in enumerate(lines) if i not in skip_lines]
with open('train_grpo.py', 'w') as f:
    f.writelines(new_lines)
print(f'train_grpo.py: removed {len(skip_lines)} lines')
